import './style.css';

const cosmetics = [
  { name: 'Emerald Explorer', type: 'Skin', category: 'Adventure', color: '#35a86b' },
    { name: 'Midnight Sheep', type: 'Skin', category: 'Special', color: '#7771b8' },
      { name: 'Forest Guardian', type: 'Cape', category: 'Nature', color: '#278c55' },
        { name: 'Sunset Wings', type: 'Cape', category: 'Special', color: '#e58a50' },
          { name: 'Frost Walker', type: 'Skin', category: 'Adventure', color: '#64a9d0' },
            { name: 'Royal Check', type: 'Cape', category: 'Classic', color: '#bd9b43' }
            ];

            let activeFilter = 'All';
            let searchText = '';

            const app = document.querySelector('#app');

            function render() {
              const filtered = cosmetics.filter(item => {
                  const matchesFilter = activeFilter === 'All' || item.type === activeFilter;
                      const matchesSearch = item.name.toLowerCase().includes(searchText.toLowerCase());
                          return matchesFilter && matchesSearch;
                            });

                              app.innerHTML = `
                                  <header class="navbar">
                                        <a class="brand" href="#">
                                                <span class="brand-icon">🐑</span>
                                                        <span>SHEEP <b>COSMETICS</b></span>
                                                              </a>
                                                                    <nav>
                                                                            <a href="#cosmetics">Cosmetics</a>
                                                                                    <a href="#how">How it works</a>
                                                                                            <a href="#account">Account</a>
                                                                                                  </nav>
                                                                                                      </header>

                                                                                                          <main>
                                                                                                                <section class="hero">
                                                                                                                        <div class="hero-content">
                                                                                                                                  <span class="eyebrow">YOUR LOOK. YOUR WORLD.</span>
                                                                                                                                            <h1>Make your<br><span>character yours.</span></h1>
                                                                                                                                                      <p>Discover unique Minecraft skins and capes. Build your style with SHEEP COSMETICS.</p>
                                                                                                                                                                <a class="primary-button" href="#cosmetics">Explore cosmetics →</a>
                                                                                                                                                                          <div class="hero-note">Built for the Minecraft community.</div>
                                                                                                                                                                                  </div>

                                                                                                                                                                                          <div class="hero-art">
                                                                                                                                                                                                    <div class="pixel-sheep">🐑</div>
                                                                                                                                                                                                              <div class="floating-tag">✦ YOUR STYLE</div>
                                                                                                                                                                                                                        <div class="floating-block"></div>
                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                      </section>

                                                                                                                                                                                                                                            <section class="catalogue" id="cosmetics">
                                                                                                                                                                                                                                                    <div class="section-heading">
                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                          <span class="eyebrow">THE COLLECTION</span>
                                                                                                                                                                                                                                                                                      <h2>Explore cosmetics</h2>
                                                                                                                                                                                                                                                                                                  <p>Find a look that represents you.</p>
                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                      <span class="item-count">${filtered.length} ITEMS</span>
                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                      <div class="toolbar">
                                                                                                                                                                                                                                                                                                                                                <input id="search" type="search" placeholder="Search cosmetics..." value="${searchText}">
                                                                                                                                                                                                                                                                                                                                                          <div class="filters">
                                                                                                                                                                                                                                                                                                                                                                      ${['All', 'Skin', 'Cape'].map(filter => `
                                                                                                                                                                                                                                                                                                                                                                                    <button class="filter ${activeFilter === filter ? 'active' : ''}" data-filter="${filter}">
                                                                                                                                                                                                                                                                                                                                                                                                    ${filter === 'Skin' ? 'Skins' : filter === 'Cape' ? 'Capes' : 'All'}
                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                              `).join('')}
                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="grid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ${filtered.length ? filtered.map(item => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <article class="card">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="preview" style="--item-color:${item.color}">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="preview-label">${item.type.toUpperCase()}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="character">🧍</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="preview-decoration">✦</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="card-info">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span class="category">${item.category}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h3>${item.name}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button class="view-button" data-name="${item.name}">View ↗</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </article>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                `).join('') : '<p class="empty">No cosmetics found. Try another search.</p>'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section class="how" id="how">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="eyebrow">GETTING STARTED</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h2>Your style in three steps.</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="steps">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <article><span>01</span><h3>Explore</h3><p>Browse skins and capes in the collection.</p></article>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <article><span>02</span><h3>Choose</h3><p>Pick the cosmetics you want for your character.</p></article>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <article><span>03</span><h3>Connect</h3><p>Link your Minecraft profile through our compatible mod.</p></article>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <section class="notice" id="account">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h2>Made for Minecraft players.</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>Website accounts, uploads, Minecraft linking and live cosmetic syncing are not implemented yet. These sample items are previews only.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </main>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <footer>© 2026 SHEEP COSMETICS <span>Made for the Minecraft community.</span></footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelector('#search').addEventListener('input', event => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    searchText = event.target.value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const position = event.target.selectionStart;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const input = document.querySelector('#search');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    input.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        input.setSelectionRange(position, position);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll('[data-filter]').forEach(button => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                button.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      activeFilter = button.dataset.filter;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.querySelectorAll('[data-name]').forEach(button => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        button.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              alert(`${button.dataset.name}\n\nThis is a sample preview. Cosmetic application will be added later.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    render();